build_daily_climatology <- function(daily_inventory, template) { x<-daily_inventory[daily_inventory$valid&&!daily_inventory$estimated,]; if(!nrow(x)) return(list()); lapply(split(x,x$date),function(z) terra::rast(z$path)) }
build_weekly_climatology <- function(weekly_inventory, template) { x<-weekly_inventory[weekly_inventory$valid&&!weekly_inventory$estimated,]; if(!nrow(x)) return(list()); lapply(split(x,weekly_inventory$iso_week),function(z) terra::rast(z$path)) }
fill_future_daily_analogs <- function(daily_dir,target_date,prefix="mintemp",overwrite=TRUE) { inv<-inventory_grid_directory(daily_dir,prefix,"daily",TRUE); obs<-inv[inv$valid&&!inv$estimated,]; if(!nrow(obs)) return(character()); target_date<-as.Date(target_date); latest<-max(obs$date); future<-seq(latest+1,target_date,by="day"); donors<-split(obs,format(obs$date,"%m-%d")); out<-character(); for(d in future) { key<-format(d,"%m-%d"); z<-donors[[key]]; if(is.null(z)&&key=="02-29") z<-donors[["02-28"]]; if(is.null(z)) next; r<-terra::app(terra::rast(z$path),mean,na.rm=TRUE); p<-file.path(daily_dir,format_daily_filename(prefix,d,TRUE)); if(!file.exists(p)||overwrite) { terra::writeRaster(r,p,overwrite=TRUE); out<-c(out,p) } }; out }
fill_future_weekly_analogs <- function(weekly_dir,target_date,prefix="mintemp",week53_method="adjacent_weeks_mean",overwrite=TRUE) { inv<-inventory_grid_directory(weekly_dir,prefix,"weekly",TRUE); obs<-inv[inv$valid&&!inv$estimated,]; if(!nrow(obs)) return(character()); latest<-max(obs$date); target_date<-as.Date(target_date); weeks<-seq(latest+7,target_date,by="7 days"); out<-character(); for(d in weeks) { w<-strftime(d,"%G-W%V"); y<-as.integer(substr(w,1,4)); k<-as.integer(substr(w,7,8)); z<-obs[obs$iso_week==k,]; if(!nrow(z)&&k==53&&week53_method=="adjacent_weeks_mean") z<-obs[obs$iso_week%in%c(1,52),]; if(!nrow(z)) next; r<-terra::app(terra::rast(z$path),mean,na.rm=TRUE); p<-file.path(weekly_dir,format_weekly_filename(prefix,y,k,TRUE)); if(!file.exists(p)||overwrite) { terra::writeRaster(r,p,overwrite=TRUE); out<-c(out,p) } }; out }
